const WIN_PATTERN_LABELS = {
  کامل: "Final row win",
  تورنا: "Column win (Tourna)",
  خطی: "Line",
  نامشخص: "Unknown",
  ROW: "Final row win",
  COL: "Column win (Tourna)",
  FULL: "Final row win",
  LINE: "Line win (5 numbers)",
  FULL_CARD: "Full-card win (15 numbers)",
  TOURNA: "Tourna (3 numbers in one row)",
};

function repairMojibakeText(raw) {
  const text = String(raw || "");
  const maybeBroken = Array.from(text).some((ch) => {
    const code = ch.charCodeAt(0);
    return code >= 0x00c0 && code <= 0x00ff;
  });
  if (!maybeBroken || typeof TextDecoder === "undefined") return text;
  try {
    const bytes = Uint8Array.from(Array.from(text).map((ch) => ch.charCodeAt(0) & 0xff));
    const repaired = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    return repaired || text;
  } catch (_) {
    return text;
  }
}

function normalizeWinPatternLabel(raw) {
  const val = repairMojibakeText(raw).trim();
  if (!val) return "-";
  if (WIN_PATTERN_LABELS[val]) return WIN_PATTERN_LABELS[val];
  const upper = val.toUpperCase();
  if (WIN_PATTERN_LABELS[upper]) return WIN_PATTERN_LABELS[upper];
  return val;
}

function winnerKindLabelByReason(reason, rule = "LEGACY") {
  const key = String(reason || "").toUpperCase();
  const gameRule = String(rule || "LEGACY").toUpperCase();
  if (key === "PRIZE_COL") return gameRule === "LINE" ? "Tourna (3 numbers in one row)" : "Column win (Tourna)";
  if (key === "PRIZE_ROW") {
    if (gameRule === "FULL_CARD") return "Full-card win (15 numbers)";
    if (gameRule === "LINE") return "Line win (5 numbers)";
    return "Final row win";
  }
  return "Win";
}

function winnerKindLabelByFlags({ row = false, col = false, rule = "LEGACY" } = {}) {
  const gameRule = String(rule || "LEGACY").toUpperCase();
  if (gameRule === "FULL_CARD") return row ? "Full-card win (15 numbers)" : "";
  if (gameRule === "LINE") {
    if (row && col) return "Tourna (3 numbers) + Line (5 numbers)";
    if (row) return "Line win (5 numbers)";
    if (col) return "Tourna (3 numbers)";
    return "";
  }
  if (row && col) return "Column win (Tourna) + Row win (final)";
  if (row) return "Final row win";
  if (col) return "Column win (Tourna)";
  return "";
}


function toEnglishDigits(raw) {
  return String(raw || "")
    .replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)));
}

function parsePositiveInt(raw) {
  const normalized = toEnglishDigits(String(raw || "")).trim();
  if (!normalized) return 0;
  if (/[^0-9,٬،_\s]/.test(normalized)) return 0;
  const cleaned = normalized.replace(/[,٬،_\s]/g, "");
  if (!/^\d+$/.test(cleaned)) return 0;
  const n = Number(cleaned);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.trunc(n));
}

function telegramInitData() {
  return String(tg?.initData || "").trim();
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, Math.max(0, Number(ms) || 0)));
}

function isNetworkFetchError(err) {
  const msg = String(err?.message || err || "").toLowerCase();
  return (
    msg.includes("failed to fetch") ||
    msg.includes("networkerror") ||
    msg.includes("load failed") ||
    msg.includes("network request failed")
  );
}

async function fetchWithRetry(path, options, retries = 1) {
  try {
    return await fetch(path, options);
  } catch (err) {
    if (retries > 0 && isNetworkFetchError(err)) {
      await sleep(FETCH_RETRY_DELAY_MS);
      return fetchWithRetry(path, options, retries - 1);
    }
    throw err;
  }
}

function idem(prefix) {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

function localizeApiError(detail) {
  const raw = knownText(String(detail || "").trim());
  if (!raw) return "Unknown error";
  const low = raw.toLowerCase();
  const exactMap = {
    forbidden: "Insufficient permissions.",
    "game not found": "Game not found.",
    "user not found": "User not found.",
    "receipt file not found": "Receipt file not found.",
    "deposit_request not found": "Deposit request not found.",
    "wallet not found": "Your wallet was not found. Please add funds first.",
    "insufficient balance": "Insufficient wallet balance to buy cards.",
    "wallet balance became negative": "A wallet security error occurred. No action was taken.",
    "game is not in lobby": "Cards can only be purchased before the game starts.",
    "prize locked": "This game is locked; cards cannot be purchased.",
    "amount must be > 0": "Amount must be greater than zero.",
    "super admin required": "Only superadmins may perform this action.",
    "super admin owner required": "Only the owner superadmin may perform this action.",
    "missing authorization": "Authentication required.",
    "missing telegram init data": "Telegram authentication data is missing.",
    "invalid live_url": "Invalid live stream link.",
    "live_url is required": "A live stream link is required.",
    "live_url is too long": "Live stream link exceeds the allowed length.",
    "cannot revoke your own super admin role": "You cannot remove your own superadmin role.",
    "cannot revoke last super admin": "The last superadmin role cannot be removed.",
    "cannot start: at least 2 unique players are required": "At least 2 distinct players must hold cards before the game can start.",
    "super admin owner required": "Only the owner superadmin may perform this action.",
    "only game admin can manage this game": "Only this game's administrator may perform this action.",
    "invalid bot token": "Invalid bot service token.",
  };
  if (exactMap[low]) return exactMap[low];

  if (low.includes("invalid hash")) {
    return "Invalid Telegram authentication. Open the Mini App from the official bot menu.";
  }
  if (low.includes("insufficient balance")) {
    return "Insufficient wallet balance to buy cards.";
  }
  if (low.includes("wallet not found")) {
    return "Your wallet was not found. Please add funds first.";
  }
  if (low.includes("game is not in lobby")) {
    return "Cards can only be purchased before the game starts.";
  }
  if (low.includes("json decode error")) {
    return "Invalid data format.";
  }
  if (
    low.includes("name or service not known") ||
    low.includes("order book has no asks") ||
    low.includes("rate provider") ||
    low.includes("دریافت نرخ لحظه‌ای ممکن نشد")
  ) {
    return "The exchange rate is temporarily unavailable. Please try again shortly.";
  }
  if (low.includes("input should be greater than")) {
    return "One of the submitted values is below the allowed minimum.";
  }
  if (low.includes("field required")) {
    return "Some required fields are missing.";
  }
  if (low.includes("[object object]")) {
    return "The submitted input is invalid.";
  }
  if (low === "http 401") {
    return "Your Mini App session expired. Reopen it from the official bot menu.";
  }
  if (low === "http 403") {
    return "You do not have permission for this action.";
  }
  if (low.startsWith("http 5")) {
    return "An internal service error occurred. Please try again shortly.";
  }
  if (low.startsWith("http ")) return "Could not connect to the server.";
  return raw;
}

