function normalizeIntList(values) {
  if (!Array.isArray(values)) return [];
  return [...new Set(values.map((x) => Number(x)).filter((x) => Number.isFinite(x) && x > 0))];
}

function liveEventCursorKnown(gameId) {
  const gid = String(Number(gameId || 0));
  return gid !== "0" && Object.prototype.hasOwnProperty.call(state.liveEventCursorByGame || {}, gid);
}

function getLiveEventCursor(gameId) {
  const gid = String(Number(gameId || 0));
  return Number((state.liveEventCursorByGame || {})[gid] || 0);
}

function markLiveEventCursor(gameId, eventId) {
  const gid = Number(gameId || 0);
  const eid = Number(eventId || 0);
  if (!gid) return;
  state.liveEventCursorByGame[String(gid)] = Math.max(getLiveEventCursor(gid), Number.isFinite(eid) ? eid : 0);
  state.lastEventId = Math.max(Number(state.lastEventId || 0), getLiveEventCursor(gid));
}

function userWinnerSeenStorageKey() {
  const uid = Number(state.currentUserId || 0);
  return `davarna_user_winner_seen_v1:${uid > 0 ? uid : "anon"}`;
}

function ensureUserWinnerSeenLoaded() {
  const storageKey = userWinnerSeenStorageKey();
  if (state.userWinnerSeenStorageKey === storageKey) return;
  state.userWinnerSeenStorageKey = storageKey;
  state.userWinnerNoticeSeen = new Set();
  try {
    const raw = localStorage.getItem(storageKey);
    const keys = JSON.parse(raw || "[]");
    if (Array.isArray(keys)) keys.forEach((key) => state.userWinnerNoticeSeen.add(String(key)));
  } catch (_) {}
}

function winnerEventSeenKey(event) {
  const payload = event?.payload || {};
  const kind = String(event?.kind || "").toUpperCase();
  const gameId = Number(event?.game_id || state.selectedGameId || 0);
  const eventId = Number(event?.id || event?.event_id || 0);
  if (eventId > 0) return `${kind}:${gameId}:${eventId}`;
  return `${kind}:${gameId}:${payload.call_number || ""}:${normalizeIntList(payload.winner_user_ids || []).join("-")}:${normalizeIntList(payload.winner_card_ids || []).join("-")}`;
}

function hasSeenWinnerEvent(event) {
  const key = winnerEventSeenKey(event);
  if (!key) return false;
  ensureUserWinnerSeenLoaded();
  return state.userWinnerNoticeSeen.has(key);
}

function rememberWinnerEventSeen(event) {
  const key = winnerEventSeenKey(event);
  if (!key) return;
  ensureUserWinnerSeenLoaded();
  state.userWinnerNoticeSeen.add(key);
  try {
    const keys = Array.from(state.userWinnerNoticeSeen).slice(-100);
    localStorage.setItem(state.userWinnerSeenStorageKey, JSON.stringify(keys));
  } catch (_) {}
}

function extractWinnerUserIds(payload) {
  if (!payload || typeof payload !== "object") return [];
  const out = [];
  const keys = ["winner_user_ids", "row_winner_user_ids", "col_winner_user_ids", "winner_ids"];
  keys.forEach((k) => {
    const vals = payload[k];
    if (Array.isArray(vals)) out.push(...vals);
  });
  if (payload.winner_user_id !== undefined && payload.winner_user_id !== null) out.push(payload.winner_user_id);
  return normalizeIntList(out);
}

function isMyWinnerEvent(event) {
  const myId = Number(state.currentUserId || 0);
  if (!myId || !event) return false;
  const kind = String(event.kind || "").toUpperCase();
  if (!["PRIZE_COL", "PRIZE_ROW", "WINNER_DECLARED"].includes(kind)) return false;
  const winners = extractWinnerUserIds(event.payload || {});
  return winners.includes(myId);
}

function buildWinnerNoticeText(event) {
  const kind = String(event?.kind || "").toUpperCase();
  const gid = Number(event?.game_id || state.selectedGameId || 0);
  const payload = event?.payload || {};
  const amount = resolveWinnerAmount(payload);
  const kindLabel = resolveWinnerKindLabel(kind, payload);
  const amountPart = amount > 0 ? ` — Amount: ${toman(amount)}` : "";
  const gamePart = gid > 0 ? ` In a game ${gameDisplayRef(gid)}` : "";
  return `Congratulations! ${kindLabel}${gamePart}${amountPart}`;
}

function resolveWinnerAmount(payload) {
  return experience.personalPrize(payload, state.currentUserId);
}

function resolveWinnerKindLabel(kind, payload) {
  return experience.prizeLabel(kind, payload);
}

function extractWinnerInfo(event) {
  const kind = String(event?.kind || "").toUpperCase();
  const payload = event?.payload || {};
  const gameId = Number(event?.game_id || state.selectedGameId || 0);
  const amount = resolveWinnerAmount(payload);
  const kindLabel = resolveWinnerKindLabel(kind, payload);
  return {
    key: `${kind}:${gameId}:${amount}:${event?.id || 0}`,
    gameId,
    amount,
    kindLabel,
  };
}

const winnerPopupQueue = [];
let activeWinnerEvent = null;

function closeWinnerModal() {
  experience.closeDialog(getEl("winnerModal"));
  activeWinnerEvent = null;
  const next = winnerPopupQueue.shift();
  if (next) openWinnerModal(next);
}

function openWinnerModal(event) {
  const modal = getEl("winnerModal");
  if (!modal || !isMyWinnerEvent(event) || hasSeenWinnerEvent(event)) return;
  const info = extractWinnerInfo(event);
  if (activeWinnerEvent) {
    if (extractWinnerInfo(activeWinnerEvent).key !== info.key && !winnerPopupQueue.some(item => extractWinnerInfo(item).key === info.key)) winnerPopupQueue.push(event);
    return;
  }
  activeWinnerEvent = event;
  rememberWinnerEventSeen(event);
  state.lastWinnerModalKey = info.key;
  const rows = experience.prizeRows(event.payload).filter(row => row.userId === Number(state.currentUserId));
  getEl("winnerModalKind").textContent = info.kindLabel;
  getEl("winnerModalAmount").textContent = info.amount !== null ? toman(info.amount) : "Your individual share cannot be verified yet";
  getEl("winnerModalGame").textContent = `Game ${gameDisplayRef(info.gameId)} · ${rows.length ? `${toFaDigits(rows.length)} Winning card` : "Card details are being checked"}`;
  getEl("winnerModalStatus").textContent = "The game result is recorded; check your wallet receipt for payment status.";
  getEl("winnerCardDetails").innerHTML = rows.map(row => `<div class="winner-card-share"><span>${safeText(winnerCardRef(info.gameId, row.cardId))}</span><strong>${safeText(toman(row.amount))}</strong></div>`).join("");
  getEl("winnerGameBtn").onclick = async () => {
    try { await openLiveGame(info.gameId, { announce: false }); closeWinnerModal(); switchToView("games"); }
    catch (error) { showToast(localizeApiError(error?.message || error), "error"); }
  };
  experience.openDialog(modal, closeWinnerModal);
  if (state.countdownVibration && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    try { tg?.HapticFeedback?.notificationOccurred?.("success"); } catch (_) {}
  }
  playWinnerSound();
}

function pushWinnerNotice(event) {
  if (!event || !isMyWinnerEvent(event) || hasSeenWinnerEvent(event)) return;
  setBadge("success", buildWinnerNoticeText(event));
  state.userFlags.recentWinner = true;
  updateHeaderStatus();
  openWinnerModal(event);
}

function renderWinnerBannerFromState(gameId, st) {
  const host = getEl("liveWinnerBanner");
  if (!host) return;
  const myId = Number(state.currentUserId || 0);
  const rowMine = myId > 0 && normalizeIntList(st?.row_winner_user_ids).includes(myId);
  const colMine = myId > 0 && normalizeIntList(st?.col_winner_user_ids).includes(myId);
  if (!rowMine && !colMine) { host.innerHTML = ""; return; }
  const notes = [];
  if (colMine) notes.push(experience.prizeLabel("PRIZE_COL", st));
  if (rowMine) notes.push(experience.prizeLabel("PRIZE_ROW", st));
  host.innerHTML = `<div class="winner-banner"><strong>Your win has been recorded</strong><span>${safeText(notes.join(" | "))}</span><span>Check your wallet receipt for your share and payment status.</span></div>`;
}

function renderGameTimeline(game, st) {
  const root = getEl("gameTimeline");
  if (!root) return;
  const status = String(st?.status || game?.status || "").toUpperCase();
  const calledCount = Number(st?.called_count || (Array.isArray(st?.called_numbers) ? st.called_numbers.length : 0));
  const rowPaid = Number(st?.row_paid || 0) === 1;
  const colPaid = Number(st?.col_paid || 0) === 1;

  let stage = 1;
  if (status === "LOBBY") stage = 1;
  if (status === "RUNNING") stage = calledCount < 35 ? 2 : 3;
  if (rowPaid || colPaid) stage = Math.max(stage, 4);
  if (status === "ENDED") stage = 5;

  const gameRule = String(st?.game_rule || game?.game_rule || "LEGACY").toUpperCase();
  const labels = gameRule === "FULL_CARD"
    ? ["Lobby", "Start", "Mid-game", "Complete card", "End"]
    : ["Lobby", "Start", "Mid-game", "Tourna", "End"];
  root.innerHTML = labels
    .map((label, idx) => {
      const n = idx + 1;
      const cls = n < stage ? "timeline-step done" : n === stage ? "timeline-step active" : "timeline-step";
      return `<div class="${cls}">${label}</div>`;
    })
    .join("");
}

function renderLiveInsights(st) {
  const root = getEl("liveInsights");
  if (!root) return;
  const remain = Number(st?.remaining_players_estimate || 0);
  const calledCount = Number(st?.called_count || (Array.isArray(st?.called_numbers) ? st.called_numbers.length : 0));
  const progress = Number(st?.called_progress_pct || 0);
  root.innerHTML = `
    <div class="live-insight">
      <div class="k">Remaining players</div>
      <div class="v">${safeText(remain || "-")}</div>
    </div>
    <div class="live-insight">
      <div class="k">Called numbers</div>
      <div class="v">${safeText(calledCount)}</div>
    </div>
    <div class="live-insight">
      <div class="k">Game progress</div>
      <div class="v">${safeText(progress)}%</div>
    </div>
  `;
}

function normalizeSafeHttpUrl(raw) {
  const text = String(raw || "").trim();
  if (!text) return null;
  if (!/^https?:\/\//i.test(text)) return null;
  return text;
}

function renderLiveLink(st) {
  const section = getEl("liveLinkSection");
  const anchor = getEl("liveLinkAnchor");
  const meta = getEl("liveLinkMeta");
  if (!section || !anchor) return;

  const url = normalizeSafeHttpUrl(st?.live_link_url);
  if (!url) {
    section.classList.add("hidden");
    anchor.removeAttribute("href");
    if (meta) meta.textContent = "";
    return;
  }

  section.classList.remove("hidden");
  anchor.setAttribute("href", url);
  if (meta) {
    const updated = String(st?.live_link_updated_at || "").trim();
    meta.textContent = updated ? `Last updated: ${formatFaDateTime(updated)}` : "A live stream link has been provided by the administrator.";
  }
}

function updateBuyActionState({ statusKey, myCardsCount }) {
  renderGameJourney();
  const actionForm = getEl("buyActionForm");
  const actionHint = getEl("liveActionHint");
  const buyHint = getEl("buyStatusHint");
  const buyBtn = getEl("buyCardsBtn");

  const canBuy = Boolean(state.selectedGameId) && String(statusKey || "").toUpperCase() === "LOBBY";
  if (actionForm) actionForm.classList.toggle("hidden", !canBuy);
  if (buyBtn) {
    buyBtn.disabled = !canBuy || purchaseInFlight;
    buyBtn.classList.toggle("disabled", !canBuy);
  }

  if (buyHint) {
    if (!canBuy) buyHint.textContent = "";
    else if (Number(myCardsCount || 0) <= 0) buyHint.textContent = "You have not bought a card yet. Join the game now.";
    else buyHint.textContent = "";
  }

  if (actionHint) {
    if (!state.selectedGameId) {
      actionHint.textContent = "Open a game first to buy cards.";
    } else if (!canBuy) {
      actionHint.textContent = "Cards can only be purchased before the game starts.";
    } else {
      actionHint.textContent = "";
    }
  }
}

function renderLiveEvents(events, { notifyFresh = false, notifyAfterId = 0, gameRule = "LEGACY" } = {}) {
  const evRoot = getEl("liveEvents");
  if (!evRoot) return;
  const list = Array.isArray(events) ? events.slice(-LIVE_EVENTS_LIMIT) : [];
  evRoot.innerHTML = list.length
    ? list
        .map((e) => {
          const mine = isMyWinnerEvent(e);
          const chipClass = mine ? "event-chip winner-event" : "event-chip";
          const winnerText = mine
            ? "<div class=\"winner-note\">Congratulations! This win has been recorded for you.</div>"
            : "";
          return `
          <div class="${chipClass}">
            <strong>${safeText(eventKindLabel(e.kind, e.payload || {}, gameRule))}</strong>
            <div>${safeText(formatFaDateTime(e.created_at))}</div>
            ${winnerText}
          </div>`;
        })
        .join("")
    : "<div class=\"empty\">No events recorded yet.</div>";
  if (notifyFresh) {
    list
      .filter((e) => Number(e?.id || 0) > Number(notifyAfterId || 0))
      .forEach((e) => {
        pushWinnerNotice(e);
        pushAdminWinnerNotice(e);
      });
  }
}

function renderLive(snapshot, options = {}) {
  const stateBox = getEl("liveState");
  if (!stateBox) return;

  const game = snapshot.game;
  const st = snapshot.state || {};
  state.gameSnapshots.set(Number(game.id), snapshot);

  if (liveGameMeta) {
    liveGameMeta.textContent = `${game.display_code || toFaDigits(game.id)} | ${statusLabel(game.status)} | ${gameRuleUiMeta(game, snapshot).label}`;
  }

  const called = Array.isArray(st.called_numbers) ? st.called_numbers : [];
  const tailNumbers = called.slice(-45);
  const lastNow = st.last_number ?? (called.length ? called[called.length - 1] : null);
  const prevLast = state.latestLiveNumberByGame[Number(game.id)];
  const lastFresh = prevLast !== undefined && lastNow != null && Number(lastNow) !== Number(prevLast);
  state.latestLiveNumberByGame[Number(game.id)] = lastNow;
  const lastNumberClass = lastFresh ? "last-number-pop fresh" : "last-number-pop";
  const calledGrid = tailNumbers.length
    ? tailNumbers
        .map((n) => {
          const isFresh = Number(lastNow) === Number(n) && lastFresh;
          return `<span class="${isFresh ? "live-called-chip fresh" : "live-called-chip"}">${safeText(n)}</span>`;
        })
        .join("")
    : "<div class=\"empty\">No numbers called yet.</div>";

  stateBox.innerHTML = `
    <div id="liveWinnerBanner"></div>
    <div class="live-main live-main-pro">
      <div class="live-top">
        <div>
          <div>Status: <strong>${safeText(statusLabel(st.status || game.status))}</strong></div>
          <div>Total prize: <strong>${toman(st.prize_pool ?? game.prize_pool)}</strong></div>
          <div class="meta">Called numbers: ${safeText(st.called_count || called.length)}</div>
        </div>
        <div class="live-last-wrap">
          <div class="live-last-label">Last number</div>
          <div class="${lastNumberClass}">${safeText(lastNow ?? "-")}</div>
        </div>
      </div>
      <div class="live-called-grid">${calledGrid}</div>
    </div>
  `;

  if (!focusGameId && lastFresh && lastNow !== null && lastNow !== undefined) {
    playNumberFeedback();
  }

  renderWinnerBannerFromState(game.id, st);
  renderGameTimeline(game, st);
  renderLiveInsights(st);
  renderLiveLink(st);
  updateBuyActionState({
    statusKey: String(st.status || game.status || "").toUpperCase(),
    myCardsCount: Number(st.my_cards_count || 0),
  });
  renderLiveEvents(snapshot.recent_events || [], {
    notifyFresh: Boolean(options.notifyFresh),
    notifyAfterId: Number(options.notifyAfterId || 0),
    gameRule: st.game_rule || game.game_rule || "LEGACY",
  });
  renderFocusSnapshot(snapshot);
  renderLiveGameBar(state.gamesCache);
}

function pickAutoLiveGameId(gameItems) {
  const items = Array.isArray(gameItems) ? gameItems : [];
  const activeIds = new Set(items.map((g) => Number(g?.id || 0)).filter((x) => x > 0));
  const current = Number(state.selectedGameId || 0);
  if (current > 0 && activeIds.has(current)) return current;
  const running = items.find((g) => String(g?.status || "").toUpperCase() === "RUNNING");
  if (running) return Number(running.id || 0);
  const lobby = items.find((g) => String(g?.status || "").toUpperCase() === "LOBBY");
  return lobby ? Number(lobby.id || 0) : 0;
}

function renderLiveSnapshot(snapshot, gameId, options = {}) {
  const gid = Number(snapshot?.game?.id || gameId || 0);
  if (!gid) return;
  const previousCursor = Number(options.notifyAfterId ?? getLiveEventCursor(gid));
  const canNotify = Boolean(options.notifyFresh) && liveEventCursorKnown(gid);
  const lastEventId = Number(snapshot?.last_event_id || 0);
  if (lastEventId < getLiveEventCursor(gid)) return;
  state.selectedGameId = gid;
  renderLive(snapshot, { notifyFresh: canNotify, notifyAfterId: previousCursor });
  markLiveEventCursor(gid, lastEventId);
  if (options.startPolling !== false) startEventPolling();
}

async function syncAutoLiveGame(gameItems) {
  if (focusGameId) return;
  const gid = pickAutoLiveGameId(gameItems);
  if (!gid) return;
  try {
    const cached = state.gameSnapshots.get(gid);
    if (cached) {
      renderLiveSnapshot(cached, gid);
      return;
    }
    const snapshot = await apiFetch(`/mini-api/games/${gid}/snapshot?events_limit=${LIVE_EVENTS_LIMIT}`);
    state.gameSnapshots.set(gid, snapshot);
    renderLiveSnapshot(snapshot, gid);
  } catch (err) {
    console.warn("[mini] auto live snapshot failed", err);
  }
}

async function openLiveGame(gameId, options = {}) {
  const gid = Number(gameId);
  state.selectedGameId = gid;
  const previousCursor = Number(options.notifyAfterId ?? getLiveEventCursor(gid));
  const snapshot = await apiFetch(`/mini-api/games/${gid}/snapshot?events_limit=${LIVE_EVENTS_LIMIT}`);
  if (Number(state.selectedGameId) !== gid) return;
  renderLiveSnapshot(snapshot, gid, {
    notifyFresh: Boolean(options.notifyFresh),
    notifyAfterId: previousCursor,
  });
  hydrateAdminCallPanelFromSnapshot(gameId, snapshot);
  if (options.announce !== false) setHint("liveActionHint", `Game ${gameDisplayRef(gameId)} selected.`, "success");
}

function appendEvents(events) {
  if (!events?.length) return;
  const evRoot = getEl("liveEvents");
  if (!evRoot) return;

  const html = events
    .map((e) => {
      const mine = isMyWinnerEvent(e);
      const chipClass = mine ? "event-chip winner-event" : "event-chip";
      const winnerText = mine ? "<div class=\"winner-note\">Congratulations! This win has been recorded for you.</div>" : "";
      return `
      <div class="${chipClass}">
        <strong>${safeText(eventKindLabel(e.kind, e.payload || {}, state.gameSnapshots.get(Number(e.game_id || state.selectedGameId || 0))?.state?.game_rule || state.gameSnapshots.get(Number(e.game_id || state.selectedGameId || 0))?.game?.game_rule || "LEGACY"))}</strong>
        <div>${safeText(formatFaDateTime(e.created_at))}</div>
        ${winnerText}
      </div>`;
    })
    .join("");

  evRoot.insertAdjacentHTML("beforeend", html);
  while (evRoot.children.length > LIVE_EVENTS_LIMIT) {
    evRoot.removeChild(evRoot.firstElementChild);
  }
  evRoot.scrollTop = evRoot.scrollHeight;

  events.forEach((e) => { pushWinnerNotice(e); pushAdminWinnerNotice(e); });
}


function miniSocketUrl() {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return `${proto}//${window.location.host}/mini-api/ws`;
}

function isMiniSocketOpen() {
  return Boolean(state.miniSocket && state.miniSocket.readyState === WebSocket.OPEN && state.miniSocketConnected);
}

function sendMiniSocket(payload) {
  if (!isMiniSocketOpen()) return false;
  try {
    state.miniSocket.send(JSON.stringify(payload));
    return true;
  } catch (_) {
    return false;
  }
}

function subscribeLiveSocket(gameId) {
  const gid = Number(gameId || state.selectedGameId || 0);
  state.miniSocketLiveGameId = gid;
  if (!gid) return;
  if (sendMiniSocket({ type: "subscribe_live", game_id: gid })) {
    stopEventPolling();
  }
}

function subscribeAdminSocket() {
  if (!state.admin.enabled) return;
  sendMiniSocket({ type: "subscribe_admin", enabled: true });
}

function subscribeCryptoSocket(invoiceId) {
  const id = Number(invoiceId || state.cryptoCurrentInvoice?.id || 0);
  state.miniSocketCryptoInvoiceId = id;
  if (!id) return;
  sendMiniSocket({ type: "subscribe_crypto", invoice_id: id });
}

function unsubscribeCryptoSocket() {
  state.miniSocketCryptoInvoiceId = 0;
  sendMiniSocket({ type: "unsubscribe_crypto" });
}

function scheduleMiniSocketReconnect() {
  if (state.miniSocketManualClose || !state.authReady || !state.token) return;
  if (state.miniSocketReconnectTimer) clearTimeout(state.miniSocketReconnectTimer);
  state.miniSocketReconnectTimer = setTimeout(() => {
    state.miniSocketReconnectTimer = null;
    startMiniSocket();
  }, MINI_SOCKET_RECONNECT_MS);
}

function stopMiniSocket() {
  state.miniSocketManualClose = true;
  if (state.miniSocketReconnectTimer) clearTimeout(state.miniSocketReconnectTimer);
  state.miniSocketReconnectTimer = null;
  state.miniSocketConnected = false;
  const ws = state.miniSocket;
  state.miniSocket = null;
  if (ws) {
    try { ws.close(1000, "closed"); } catch (_) {}
  }
}

function restartMiniSocket() {
  stopMiniSocket();
  state.miniSocketManualClose = false;
  if (!state.authReady || !state.token) return;
  state.miniSocketReconnectTimer = setTimeout(() => {
    state.miniSocketReconnectTimer = null;
    startMiniSocket();
  }, 120);
}

function handleMiniSocketFinance(payload) {
  if (!state.admin.enabled) return;
  const statePayload = payload?.state || {};
  const key = JSON.stringify({
    dep: statePayload.latest_pending_deposit_id || 0,
    depCount: statePayload.pending_deposit_count || 0,
    wdr: statePayload.latest_pending_withdraw_id || 0,
    wdrCount: statePayload.pending_withdraw_count || 0,
    approvedWdr: statePayload.approved_withdraw_count || 0,
  });
  if (key === state.miniSocketFinanceKey) return;
  state.miniSocketFinanceKey = key;
  checkAdminFinanceNotifications({ silent: false }).catch(() => {});
  if (isAdminViewActive()) {
    Promise.allSettled([
      refreshAdminOpsDashboard(),
      refreshAdminRiskAlerts(),
      refreshAdminDeposits(),
      refreshAdminWithdraws(),
    ]).catch(() => {});
  }
}

function handleMiniSocketMessage(event) {
  let payload = null;
  try {
    payload = JSON.parse(String(event?.data || "{}"));
  } catch (_) {
    return;
  }
  const type = String(payload?.type || "");
  if (type === "connected") {
    state.miniSocketConnected = true;
    subscribeAdminSocket();
    if (state.selectedGameId) subscribeLiveSocket(state.selectedGameId);
    if (state.miniSocketCryptoInvoiceId || isCryptoInvoicePending(state.cryptoCurrentInvoice)) {
      subscribeCryptoSocket(state.miniSocketCryptoInvoiceId || state.cryptoCurrentInvoice?.id);
    }
    return;
  }
  if (type === "live_snapshot") {
    const gid = Number(payload.game_id || payload.snapshot?.game?.id || 0);
    if (!gid || Number(state.selectedGameId || 0) !== gid) return;
    const snapshot = payload.snapshot;
    if (!snapshot) return;
    const previousCursor = getLiveEventCursor(gid);
    renderLiveSnapshot(snapshot, gid, {
      notifyFresh: true,
      notifyAfterId: previousCursor,
      startPolling: false,
    });
    if (state.admin.enabled && Number(state.admin?.selectedGameId || 0) === gid) {
      refreshAdminAutoDraw(gid).catch(() => {});
    }
    return;
  }
  if (type === "finance_status") {
    handleMiniSocketFinance(payload);
    return;
  }
  if (type === "crypto_invoice") {
    const invoice = payload?.invoice;
    const id = Number(payload?.invoice_id || invoice?.id || 0);
    if (!invoice || !id || Number(state.cryptoCurrentInvoice?.id || 0) !== id) return;
    const previousStatus = String(state.cryptoCurrentInvoice?.status || "");
    renderCryptoInvoice(invoice, { open: state.cryptoInvoiceViewOpen });
    const nextStatus = String(invoice.status || "");
    if (nextStatus !== previousStatus && nextStatus === "CREDITED") {
      triggerLightHaptic("success");
      refreshWallet().catch(() => {});
    }
  }
}

function startMiniSocket() {
  if (!("WebSocket" in window)) return;
  if (!state.authReady || !state.token) return;
  if (state.miniSocket && [WebSocket.OPEN, WebSocket.CONNECTING].includes(state.miniSocket.readyState)) return;

  state.miniSocketManualClose = false;
  const ws = new WebSocket(miniSocketUrl());
  state.miniSocket = ws;

  ws.addEventListener("open", () => {
    try {
      ws.send(JSON.stringify({ type: "auth", token: state.token }));
    } catch (_) {}
  });
  ws.addEventListener("message", handleMiniSocketMessage);
  ws.addEventListener("close", () => {
    if (state.miniSocket === ws) state.miniSocket = null;
    state.miniSocketConnected = false;
    if (!state.miniSocketManualClose && state.selectedGameId) startEventPolling();
    scheduleMiniSocketReconnect();
  });
  ws.addEventListener("error", () => {
    try { ws.close(); } catch (_) {}
  });

  const markConnected = (event) => {
    try {
      const payload = JSON.parse(String(event?.data || "{}"));
      if (payload?.type === "connected") {
        state.miniSocketConnected = true;
        ws.removeEventListener("message", markConnected);
      }
    } catch (_) {}
  };
  ws.addEventListener("message", markConnected);
}

function startEventPolling() {
  stopEventPolling();
  if (!state.selectedGameId) return;
  if (isMiniSocketOpen()) {
    subscribeLiveSocket(state.selectedGameId);
    return;
  }
  state.pollTimer = setInterval(async () => {
    try {
      const gid = Number(state.selectedGameId || 0);
      const previousCursor = getLiveEventCursor(gid);
      const events = await apiFetch(
        `/mini-api/games/${gid}/events?after_id=${previousCursor}&limit=${LIVE_EVENTS_LIMIT}`
      );
      if (events?.length && gid === Number(state.selectedGameId)) {
        const snap = await apiFetch(`/mini-api/games/${gid}/snapshot?events_limit=${LIVE_EVENTS_LIMIT}`);
        if (gid !== Number(state.selectedGameId)) return;
        renderLiveSnapshot(snap, gid, {
          notifyFresh: true,
          notifyAfterId: previousCursor,
          startPolling: false,
        });
        if (state.admin.enabled && Number(state.admin?.selectedGameId || 0) === gid) {
          refreshAdminAutoDraw(gid).catch(() => {});
        }
      }
    } catch (_) {}
  }, 1200);
}

function stopEventPolling() {
  if (state.pollTimer) clearInterval(state.pollTimer);
  state.pollTimer = null;
}

async function refreshAutoTick() {
  const tasks = [refreshGames(), refreshWallet()];
  if (isCardsViewActive()) {
    tasks.push(refreshCards({ silent: true }));
  }
  if (state.admin.enabled && isAdminViewActive()) {
    tasks.push(refreshAdminPanel({ silent: true }));
  }
  if (state.admin.enabled && !isMiniSocketOpen()) {
    tasks.push(checkAdminFinanceNotifications({ silent: false }));
  }
  await Promise.allSettled(tasks);
  if (state.selectedGameId && !isMiniSocketOpen()) {
    try {
      const gid = Number(state.selectedGameId || 0);
      const previousCursor = getLiveEventCursor(gid);
      const snap = await apiFetch(`/mini-api/games/${gid}/snapshot?events_limit=${LIVE_EVENTS_LIMIT}`);
      renderLiveSnapshot(snap, gid, {
        notifyFresh: liveEventCursorKnown(gid),
        notifyAfterId: previousCursor,
        startPolling: false,
      });
    } catch (_) {}
  }
}

function startGlobalRefresh() {
  stopGlobalRefresh();
  state.globalRefreshTimer = setInterval(() => {
    if (!state.authReady) return;
    refreshAutoTick().catch(() => {});
  }, GLOBAL_REFRESH_INTERVAL_MS);
  if (!state.automationPollTimer) state.automationPollTimer = setInterval(refreshAutomationTimeline, 2000);
}

let automationRequestPending = false;
async function refreshAutomationTimeline() {
  if (automationRequestPending || !state.authReady || document.visibilityState === "hidden" ||
      !getEl("view-games")?.classList.contains("active")) return;
  automationRequestPending = true;
  try {
    const data = await apiFetch("/mini-api/automation/timeline");
    const serverMs = Date.parse(String(data.server_time_utc || ""));
    if (Array.isArray(data.automation) && Number.isFinite(serverMs)) {
      gameStartCountdownServerOffsetMs = serverMs - Date.now();
      automationReceivedAt = serverMs;
      automationItems = data.automation;
      // A fresh phase can revoke an older game-list countdown immediately.
      state.gamesCache.forEach((game) => {
        const phase = automationItems.find((item) => Number(item.game_id) === Number(game.id));
        if (game.execution_source !== "SYSTEM" || game.status !== "LOBBY") return;
        game.countdown_enabled = phase?.phase === "START";
        if (game.countdown_enabled) {
          game.scheduled_start_at = phase.deadline_utc;
          game.countdown_seconds = phase.duration_seconds;
        }
      });
      renderAutomationTimeline();
      tickAutopilotGameStartClocks();
    }
  } catch (_) { tickAutomationTimeline(); }
  finally { automationRequestPending = false; }
}

function stopGlobalRefresh() {
  if (state.globalRefreshTimer) clearInterval(state.globalRefreshTimer);
  state.globalRefreshTimer = null;
  if (state.automationPollTimer) clearInterval(state.automationPollTimer);
  state.automationPollTimer = null;
}

async function refreshGames() {
  const sequence = ++gamesRequestSerial;
  const account = state.currentUserId;
  const [gamesSettled, cardsSettled, insightsSettled] = await Promise.allSettled([
    apiFetch("/mini-api/games?status=LOBBY,RUNNING&limit=30"),
    apiFetch("/mini-api/me/active-games"),
    apiFetch("/mini-api/dashboard/insights"),
  ]);

  if (sequence !== gamesRequestSerial || account !== state.currentUserId) return;
  loadEventCues();
  const gamesRes = gamesSettled.status === "fulfilled" ? gamesSettled.value : null;
  const cardsRes = cardsSettled.status === "fulfilled" ? cardsSettled.value : null;
  const insights = insightsSettled.status === "fulfilled" ? insightsSettled.value : null;

  const gameItems = Array.isArray(gamesRes?.items) ? gamesRes.items : (Array.isArray(state.gamesCache) ? state.gamesCache : []);
  const cards = Array.isArray(cardsRes?.items) ? cardsRes.items : null;
  if (Array.isArray(gamesRes?.items)) {
    // Correct client clock drift using the same server clock used by Autopilot.
    const serverMs = Date.parse(String(gamesRes.server_time_utc || ""));
    if (Number.isFinite(serverMs)) gameStartCountdownServerOffsetMs = serverMs - Date.now();
    state.gamesCache = gamesRes.items;
    if (Array.isArray(gamesRes.automation) && Number.isFinite(serverMs)) {
      automationItems = gamesRes.automation;
      automationReceivedAt = serverMs;
      renderAutomationTimeline();
    }
  }

  renderReturnGames(cards || []);
  state.myCardsByGame = new Map((cards || []).map(g => [Number(g.game_id), Number(g.card_count)]));

  if (insights) {
    state.hotGameId = null;
    state.userFlags.inGame = Boolean(insights?.in_game);
    state.userFlags.recentWinner = Boolean(insights?.recent_winner);
    state.recentGamesStats = Array.isArray(insights?.recent_games) ? insights.recent_games : [];
    state.dashboardTrust = insights?.trust || null;
  }
  updateHeaderStatus();

  const snapshotResults = await Promise.allSettled(
    gameItems.slice(0, 10).map((g) => apiFetch(`/mini-api/games/${g.id}/snapshot?events_limit=1`))
  );
  if (sequence !== gamesRequestSerial || account !== state.currentUserId) return;
  snapshotResults.forEach((res) => {
    if (res.status === "fulfilled") {
      const gid = Number(res.value?.game?.id || 0);
      if (gid) state.gameSnapshots.set(gid, res.value);
    }
  });

  await syncAutoLiveGame(gameItems);
  if (sequence !== gamesRequestSerial || account !== state.currentUserId) return;
  renderLiveGameBar(gameItems);
  drawGames(gameItems);
  drawRecentStats(state.recentGamesStats);
  drawTrustStrip(state.dashboardTrust);
}

