function compactCryptoAmount(value) {
  const raw = String(value ?? "0");
  return raw.includes(".") ? raw.replace(/0+$/, "").replace(/\.$/, "") : raw;
}

function toFaDigits(value) { return String(value ?? ""); }

function depositMethodAvailability() {
  return {
    bank: Array.isArray(state.depositDestinations) && state.depositDestinations.length > 0,
    crypto: Boolean(state.cryptoOptions?.enabled && Array.isArray(state.cryptoOptions?.options) && state.cryptoOptions.options.length),
  };
}

function setDepositMode(mode) {
  const available = depositMethodAvailability();
  const requested = mode === "crypto" ? "crypto" : "bank";
  const normalized = available[requested] ? requested : (available.bank ? "bank" : (available.crypto ? "crypto" : null));
  document.querySelectorAll(".deposit-mode-btn").forEach((btn) => {
    const active = btn.getAttribute("data-deposit-mode") === normalized;
    btn.classList.toggle("active", active);
    btn.setAttribute("aria-selected", active ? "true" : "false");
    btn.tabIndex = active ? 0 : -1;
  });
  getEl("bankDepositPanel")?.classList.toggle("hidden", normalized !== "bank");
  getEl("cryptoDepositPanel")?.classList.toggle("hidden", normalized !== "crypto");
  const description = getEl("depositFlowDesc");
  if (description) {
    description.textContent = normalized === "crypto"
      ? "1) Top-up amount 2) Choose network 3) Get exact amount and payment address"
      : normalized === "bank"
        ? "1) Amount 2) Destination card 3) Upload receipt 4) Submit"
        : "No deposit methods are currently active.";
  }
}

function syncDepositMethodAvailability() {
  const available = depositMethodAvailability();
  const bankBtn = getEl("bankDepositModeBtn");
  const cryptoBtn = getEl("cryptoDepositModeBtn");
  if (bankBtn) {
    bankBtn.classList.toggle("hidden", !available.bank);
    bankBtn.disabled = !available.bank;
  }
  if (cryptoBtn) {
    cryptoBtn.classList.toggle("hidden", !available.crypto);
    cryptoBtn.disabled = !available.crypto;
  }
  getEl("depositUnavailableNote")?.classList.toggle("hidden", available.bank || available.crypto);
  const current = document.querySelector(".deposit-mode-btn.active")?.getAttribute("data-deposit-mode") || "bank";
  setDepositMode(current);
}

function renderCryptoHealthSummary(payload) {
  const root = getEl("cryptoHealthSummary");
  if (!root) return;
  const enabled = Boolean(payload?.enabled);
  const options = Array.isArray(payload?.options) ? payload.options : [];
  if (!enabled || !options.length) {
    root.innerHTML = `
      <div class="crypto-health-card is-off">
        <strong>Crypto status</strong>
        <span>Crypto payments are currently unavailable to users.</span>
      </div>
    `;
    return;
  }
  root.innerHTML = options.map((item) => {
    const healthy = Boolean(item?.healthy);
    const network = String(item?.network || "-").toUpperCase();
    const asset = String(item?.asset || "-").toUpperCase();
    const provider = String(item?.rate_provider || "-");
    const rate = item?.rate_toman ? toman(item.rate_toman) : "-";
    const checkedAt = item?.checked_at ? formatFaDateTime(item.checked_at) : "-";
    const reason = String(item?.unavailable_reason || "").trim();
    return `
      <div class="crypto-health-card ${healthy ? "is-ok" : "is-warning"}">
        <div>
          <strong dir="ltr">${safeText(asset)} / ${safeText(network)}</strong>
          <span>${healthy ? "Last check succeeded" : safeText(reason || "Last rate lookup failed; another attempt will be made when issuing the invoice.")}</span>
        </div>
        <div class="crypto-health-meta">
          <span>Rate: <b>${safeText(rate)}</b></span>
          <span>Source: <b>${safeText(provider)}</b></span>
          <span>Last checked: <b>${safeText(checkedAt)}</b></span>
        </div>
      </div>
    `;
  }).join("");
}

function drawCryptoOptions(payload) {
  state.cryptoOptions = payload || null;
  renderCryptoHealthSummary(payload);
  const enabled = Boolean(payload?.enabled && Array.isArray(payload?.options) && payload.options.length);
  const modeBtn = getEl("cryptoDepositModeBtn");
  if (modeBtn) {
    modeBtn.disabled = !enabled;
    modeBtn.title = enabled ? "Deposit with crypto" : "Crypto deposits are disabled";
  }
  syncDepositMethodAvailability();
  const networkInput = getEl("cryptoNetworkSelect");
  if (!networkInput) return;
  const optionMap = new Map(
    (Array.isArray(payload?.options) ? payload.options : [])
      .map((item) => [String(item.network || "").toUpperCase(), item])
      .filter(([network]) => Boolean(network))
  );
  const available = new Set([...optionMap.keys()]);
  document.querySelectorAll(".crypto-network-option").forEach((button) => {
    const network = String(button.getAttribute("data-network") || "").toUpperCase();
    const option = optionMap.get(network);
    const usable = enabled && Boolean(option);
    const rateOk = Boolean(option?.healthy);
    button.disabled = !usable;
    button.classList.toggle("is-unavailable", !usable);
    button.classList.toggle("is-rate-warning", usable && !rateOk);
    button.title = usable
      ? "Network available; the current rate is retrieved when issuing the invoice."
      : "Network not enabled in payment settings.";
    let health = button.querySelector(".crypto-network-health");
    if (!health) {
      health = document.createElement("span");
      health.className = "crypto-network-health";
      button.querySelector(".crypto-network-copy")?.appendChild(health);
    }
    health.textContent = usable
      ? rateOk
        ? `Last rate ${toman(option?.rate_toman || 0)}`
        : "Available; rate retrieved at invoice creation"
      : "Not enabled in settings";
    health.dataset.state = usable ? (rateOk ? "ok" : "warning") : "error";
  });
  if (!enabled) {
    networkInput.value = "";
    setHint("cryptoNetworkHint", "Crypto deposits are not enabled on the server.");
     return;
  }
  const current = String(networkInput.value || "").toUpperCase();
  const selected = available.has(current) ? current : ([...available][0] || "");
  selectCryptoNetwork(selected, { haptic: false });
  const validity = getEl("cryptoInvoiceValidity");
  if (validity) validity.textContent = `${toFaDigits(payload.invoice_expire_minutes || 15)} minutes`;
  const daily = getEl("cryptoDailyLimit");
  if (daily) daily.textContent = toman(payload.daily_user_max_toman || 0);
  if (!selected) {
    setHint("cryptoNetworkHint", "No networks are currently enabled in crypto settings.", "error");
  } else {
    const selectedOption = cryptoOption(selected);
    setHint(
      "cryptoNetworkHint",
      selectedOption?.healthy
        ? "Last rate check succeeded. The final rate will be retrieved again when issuing the invoice."
        : "Network available; the current rate is retrieved when issuing the invoice.",
      selectedOption?.healthy ? "success" : "pending"
    );
  }
}

function cryptoOption(network) {
  const key = String(network || "").toUpperCase();
  return (state.cryptoOptions?.options || []).find(
    (item) => String(item?.network || "").toUpperCase() === key
  ) || null;
}

function selectCryptoNetwork(network, { haptic = true } = {}) {
  const normalized = String(network || "").toUpperCase();
  const input = getEl("cryptoNetworkSelect");
  if (input) input.value = normalized;
  document.querySelectorAll(".crypto-network-option").forEach((button) => {
    const selected = !button.disabled && String(button.getAttribute("data-network") || "").toUpperCase() === normalized;
    button.classList.toggle("is-selected", selected);
    button.setAttribute("aria-checked", selected ? "true" : "false");
  });
  const option = cryptoOption(normalized);
  if (option) {
    const rateTime = option.checked_at ? formatFaDateTime(option.checked_at) : "Just now";
    setHint(
      "cryptoNetworkHint",
      option.healthy
        ? `Network ready; rate checked at ${rateTime} .`
        : "Network selected; the current rate will be retrieved when issuing the invoice.",
      option.healthy ? "success" : "pending"
    );
  }
  if (haptic) triggerLightHaptic("success");
}

function isCryptoInvoicePending(invoice) {
  return ["WAITING_PAYMENT", "CONFIRMING"].includes(String(invoice?.status || "").toUpperCase());
}

function shortenCryptoAddress(value) {
  const text = String(value || "");
  if (text.length <= 24) return text;
  return `${text.slice(0, 10)}…${text.slice(-9)}`;
}

function setCryptoClosingConfirmation(enabled) {
  try {
    if (enabled) tg?.enableClosingConfirmation?.();
    else tg?.disableClosingConfirmation?.();
  } catch (_) {}
}

function stopCryptoCountdown() {
  if (state.cryptoCountdownTimer) clearInterval(state.cryptoCountdownTimer);
  state.cryptoCountdownTimer = null;
}

function updateCryptoCountdown(invoice) {
  const countdown = getEl("cryptoInvoiceCountdown");
  if (!countdown) return;
  const expiresAt = parseApiDate(invoice?.expires_at).getTime();
  if (!Number.isFinite(expiresAt)) {
    countdown.textContent = "--:--";
    return;
  }
  const now = Date.now() + Number(state.cryptoServerOffsetMs || 0);
  const remaining = Math.max(0, Math.ceil((expiresAt - now) / 1000));
  const minutes = Math.floor(remaining / 60);
  const seconds = remaining % 60;
  countdown.textContent = `${toFaDigits(minutes)}:${toFaDigits(String(seconds).padStart(2, "0"))}`;
  countdown.closest(".crypto-countdown")?.classList.toggle("is-urgent", remaining > 0 && remaining <= 120);
  if (
    remaining === 0 &&
    isCryptoInvoicePending(invoice) &&
    Number(state.cryptoExpiryRefreshId || 0) !== Number(invoice.id || 0)
  ) {
    state.cryptoExpiryRefreshId = Number(invoice.id || 0);
    refreshCryptoInvoice(invoice.id, { open: true, silent: true }).catch(() => {});
  }
}

function startCryptoCountdown(invoice) {
  stopCryptoCountdown();
  const serverNow = parseApiDate(invoice?.server_now).getTime();
  state.cryptoServerOffsetMs = Number.isFinite(serverNow) ? serverNow - Date.now() : 0;
  updateCryptoCountdown(invoice);
  if (isCryptoInvoicePending(invoice)) {
    state.cryptoCountdownTimer = setInterval(() => updateCryptoCountdown(invoice), 1000);
  }
}

function cryptoTimeline(status) {
  const key = String(status || "").toUpperCase();
  const progress = key === "CREDITED"
    ? 4
    : key === "CONFIRMING"
      ? 2
      : key === "NEEDS_REVIEW"
        ? 2
        : 1;
  const labels = ["Issue invoice", "View transaction", "Network confirmation", "Add wallet funds"];
  return labels.map((label, index) => {
    const done = index < progress;
    const active = index === progress && progress < 4;
    const warning = key === "NEEDS_REVIEW" && index === 2;
    return `
      <div class="crypto-timeline-step${done ? " is-done" : ""}${active ? " is-active" : ""}${warning ? " is-warning" : ""}">
        <i>${done ? "✓" : index + 1}</i>
        <span>${safeText(warning ? "Admin review" : label)}</span>
      </div>
    `;
  }).join("");
}

function clearCryptoQrObjectUrl() {
  if (state.cryptoQrObjectUrl) {
    try { URL.revokeObjectURL(state.cryptoQrObjectUrl); } catch (_) {}
  }
  state.cryptoQrObjectUrl = "";
  state.cryptoQrInvoiceId = 0;
}

function captureCryptoInvoiceUiState(box) {
  if (!box) return null;
  const manual = box.querySelector(".crypto-manual-payment");
  const txDetails = box.querySelector(".crypto-tx-details");
  const txInput = box.querySelector("#cryptoTxHashInput");
  const hint = box.querySelector("#cryptoInvoiceHint");
  return {
    manualOpen: manual ? Boolean(manual.open) : Boolean(state.cryptoManualPaymentOpen),
    txDetailsOpen: txDetails ? Boolean(txDetails.open) : Boolean(state.cryptoTxDetailsOpen),
    txHashDraft: txInput ? String(txInput.value || "") : String(state.cryptoTxHashDraft || ""),
    hintText: hint ? String(hint.textContent || "") : String(state.cryptoInvoiceHintText || ""),
    hintType: hint ? String(hint.dataset?.type || "") : String(state.cryptoInvoiceHintType || ""),
  };
}

function restoreCryptoInvoiceUiState(box, invoice, captured = null) {
  if (!box || !invoice) return;
  const manual = box.querySelector(".crypto-manual-payment");
  const txDetails = box.querySelector(".crypto-tx-details");

  if (manual) {
    state.cryptoManualPaymentOpen = Boolean(captured?.manualOpen ?? state.cryptoManualPaymentOpen);
    manual.open = state.cryptoManualPaymentOpen;
    manual.addEventListener("toggle", () => {
      state.cryptoManualPaymentOpen = Boolean(manual.open);
    });
  }

  if (txDetails) {
    state.cryptoTxDetailsOpen = Boolean(captured?.txDetailsOpen ?? state.cryptoTxDetailsOpen);
    txDetails.open = state.cryptoTxDetailsOpen;
    txDetails.addEventListener("toggle", () => {
      state.cryptoTxDetailsOpen = Boolean(txDetails.open);
    });
  }

  if (captured) {
    state.cryptoTxHashDraft = String(captured.txHashDraft || state.cryptoTxHashDraft || "");
    state.cryptoInvoiceHintText = String(captured.hintText || state.cryptoInvoiceHintText || "");
    state.cryptoInvoiceHintType = String(captured.hintType || state.cryptoInvoiceHintType || "");
  }

  const txInput = box.querySelector("#cryptoTxHashInput");
  if (txInput) {
    if (state.cryptoTxHashDraft && txInput.value !== state.cryptoTxHashDraft) {
      txInput.value = state.cryptoTxHashDraft;
    }
    txInput.addEventListener("input", () => {
      state.cryptoTxHashDraft = String(txInput.value || "");
    });
  }

  setHint("cryptoInvoiceHint", state.cryptoInvoiceHintText, state.cryptoInvoiceHintType);
}

function setCryptoInvoiceView(open) {
  const active = Boolean(open);
  const wasOpen = Boolean(state.cryptoInvoiceViewOpen);
  state.cryptoInvoiceViewOpen = active;
  document.body.classList.toggle("crypto-payment-active", active);
  getEl("view-wallet")?.classList.toggle("crypto-payment-active", active);
  getEl("cryptoCreateView")?.classList.toggle("hidden", active);
  getEl("cryptoInvoiceBox")?.classList.toggle("hidden", !active);
  setCryptoClosingConfirmation(active && isCryptoInvoicePending(state.cryptoCurrentInvoice));
  if (active && !wasOpen) {
    requestAnimationFrame(() => {
      getEl("cryptoInvoiceBox")?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  }
  if (!active) {
    stopCryptoCountdown();
    syncCryptoActiveResume();
  }
}

function syncCryptoActiveResume() {
  const resume = getEl("cryptoActiveResume");
  const invoice = state.cryptoCurrentInvoice;
  const active = isCryptoInvoicePending(invoice);
  resume?.classList.toggle("hidden", !active);
  const meta = getEl("cryptoActiveResumeMeta");
  if (meta && active) {
    meta.textContent = `Invoice #${invoice.id} • ${compactCryptoAmount(invoice.amount_crypto)} ${invoice.asset}`;
  }
  const createButton = getEl("createCryptoInvoiceBtn");
  if (createButton) {
    createButton.textContent = active ? "Continue active invoice" : "Get rate and continue";
  }
}

function closeCryptoInvoiceView() {
  setCryptoInvoiceView(false);
  getEl("cryptoCreateView")?.scrollIntoView({ behavior: "smooth", block: "start" });
}

function rememberCryptoInvoice(invoice) {
  if (!invoice) return;
  state.cryptoCurrentInvoice = invoice;
  if (Number(state.cryptoExpiryRefreshId || 0) !== Number(invoice.id || 0)) {
    state.cryptoExpiryRefreshId = 0;
  }
  if (isCryptoInvoicePending(invoice)) {
    try { localStorage.setItem("davarna_crypto_active_invoice_id", String(invoice.id)); } catch (_) {}
    subscribeCryptoSocket(invoice.id);
  } else {
    try { localStorage.removeItem("davarna_crypto_active_invoice_id"); } catch (_) {}
    if (Number(state.miniSocketCryptoInvoiceId || 0) === Number(invoice.id || 0)) {
      unsubscribeCryptoSocket();
    }
  }
  syncCryptoActiveResume();
}

