function updateAdminActionButtons() {
  const gid = Number(state.admin?.selectedGameId || 0);
  const g = gid ? getAdminGameById(gid) : null;
  const status = String(g?.status || "").toUpperCase();
  const canManage = g?.can_manage !== false;
  const gatedActions = new Set([
    "adminStartBtn", "adminCloseLobbyBtn", "adminCallBtn", "adminUndoBtn",
    "adminDrawModeManualBtn", "adminDrawModeAutoBtn",
    "adminAutoDrawPauseBtn", "adminAutoDrawResumeBtn",
    "adminSendLiveBtn", "adminClearLiveBtn", "adminSetLiveBtn",
  ]);

  const setBtn = (id, enabled, title) => {
    const btn = getEl(id);
    if (!btn) return;
    const allowed = Boolean(enabled) && (canManage || !gatedActions.has(id));
    btn.disabled = !allowed;
    btn.classList.toggle("is-disabled", !allowed);
    const hint = !canManage && gatedActions.has(id)
      ? "You do not have permission to manage this game."
      : title;
    if (hint) btn.setAttribute("title", hint);
    else btn.removeAttribute("title");
  };

  const hasGame = gid > 0;
  const isLobby = status === "LOBBY";
  const isRunning = status === "RUNNING";
  const autoDraw = state.admin?.autoDrawByGame?.get(gid) || null;
  const autoStatus = String(autoDraw?.auto_status || autoDraw?.status || "STOPPED").toUpperCase();
  const drawMode = String(autoDraw?.draw_mode || "").toUpperCase();
  const drawLocked = Boolean(autoDraw?.locked);
  const validDrawMode = drawMode === "MANUAL" || drawMode === "AUTO";

  const hasLiveLink = Boolean(adminLiveLinkForGame(gid));

  setBtn("adminStartBtn", hasGame && isLobby && validDrawMode, !validDrawMode ? "Choose the number-calling mode before starting." : "Only lobby games can be started.");
  setBtn("adminCloseLobbyBtn", hasGame && isLobby, hasGame ? "Cancellation is only allowed before a game starts." : "Select the game first.");
  setBtn("adminCallBtn", hasGame && isRunning && drawMode === "MANUAL", drawMode === "AUTO" ? "This game is locked to automatic mode." : "Numbers can only be called in a running manual game.");
  setBtn("adminUndoBtn", hasGame && isRunning && drawMode === "MANUAL", drawMode === "AUTO" ? "Undo is unavailable for a game locked to automatic mode." : "Only the last number of a running manual game can be removed.");
  setBtn("adminDrawModeManualBtn", hasGame && isLobby && !drawLocked, "Manual mode can only be selected before the game starts.");
  setBtn("adminDrawModeAutoBtn", hasGame && isLobby && !drawLocked, "Automatic mode and interval can only be selected before the game starts.");
  setBtn("adminAutoDrawPauseBtn", hasGame && isRunning && drawMode === "AUTO" && autoStatus === "RUNNING", "Pause automatic calling; number order remains unchanged.");
  setBtn("adminAutoDrawResumeBtn", hasGame && isRunning && drawMode === "AUTO" && autoStatus === "PAUSED", "Resume the same locked sequence.");

  const intervalEl = getEl("adminAutoDrawInterval");
  if (intervalEl) intervalEl.disabled = !(hasGame && isLobby && !drawLocked && canManage);
  setBtn("adminSendLiveBtn", hasGame && hasLiveLink, hasLiveLink ? "Send the live stream link to this game's card buyers." : "Save a live stream link first.");
  setBtn("adminClearLiveBtn", hasGame && hasLiveLink, hasLiveLink ? "Remove this game's saved live stream link." : "No live stream link recorded.");
  setBtn("adminSetLiveBtn", hasGame, hasGame ? "Add or edit this game's live stream link." : "Select the game first.");
}

function requireAdminGameStatus(allowedStatuses, actionLabel) {
  const gid = requireAdminSelectedGame();
  const g = getAdminGameById(gid);
  const status = String(g?.status || "").toUpperCase();
  const allowed = new Set((allowedStatuses || []).map((x) => String(x).toUpperCase()));
  if (allowed.size && !allowed.has(status)) {
    const current = status ? statusLabel(status) : "Unknown";
    throw new Error(`${actionLabel} Not allowed for the current game status: ${current}`);
  }
  return { gid, game: g, status };
}


