async function refreshSuperBankDestinations() {
  if (!state.admin.enabled || !state.admin.canManageSuperSettings) return;
  const out = await apiFetch("/mini-api/admin/super/deposit-destinations");
  state.admin.bankDestinations = Array.isArray(out?.items) ? out.items : [];
  state.admin.bankDestinationsRevision = String(out?.revision || "");
  renderSuperBankDestinations();
}

async function saveSuperBankDestination() {
  if (!state.admin.canManageSuperSettings) throw new Error("This action is for superadmins only.");
  const id = String(state.admin.bankDestinationEditingId || "");
  const form = bankCardEditPayload();
  if (!/^[0-9]{16,19}$/.test(form.card_number)) {
    throw new Error("The card number must contain 16 to 19 digits.");
  }
  if (!form.expected_revision) throw new Error("Load the card list first.");
  if (id && !state.admin.bankDestinations.some((x) => String(x.id) === id)) {
    throw new Error("Selected card not found; refresh the list.");
  }
  const operation = id ? "Edit card" : "Add disabled card";
  const risk = id ? (form.is_active ? "This card will be enabled for user deposits after saving." : "This card will be disabled.")
    : "The new card will initially be disabled.";
  if (!window.confirm(operation + " " + maskCard(form.card_number) + "؟\n" + risk)) return;
  const button = getEl("superBankCardSaveBtn");
  if (button) button.disabled = true;
  try {
    const endpoint = "/mini-api/admin/super/deposit-destinations";
    await apiFetch(id ? endpoint + "/" + encodeURIComponent(id) : endpoint, {
      method: id ? "PUT" : "POST", body: form,
    });
    closeSuperBankCardEditor();
    await Promise.allSettled([
      refreshSuperBankDestinations(), refreshSuperBankDepositSettings(), refreshWallet()
    ]);
    setHint("superBankCardsHint", "Card information saved and list refreshed.", "success");
  } finally {
    if (button) button.disabled = false;
  }
}

async function deleteSuperBankDestination() {
  const id = String(state.admin.bankDestinationEditingId || "");
  const card = state.admin.bankDestinations.find((x) => String(x.id) === id);
  if (!card || card.is_active) throw new Error("Disable the card first.");
  if (!window.confirm("Delete disabled card " + maskCard(card.card_number) + "؟")) return;
  const button = getEl("superBankCardDeleteBtn");
  if (button) button.disabled = true;
  try {
    await apiFetch("/mini-api/admin/super/deposit-destinations/" + encodeURIComponent(id), {
      method: "DELETE", body: { expected_revision: state.admin.bankDestinationsRevision },
    });
    closeSuperBankCardEditor();
    await Promise.allSettled([
      refreshSuperBankDestinations(), refreshSuperBankDepositSettings(), refreshWallet()
    ]);
    setHint("superBankCardsHint", "Disabled card deleted.", "success");
  } finally {
    if (button) button.disabled = false;
  }
}

function renderSuperBankDepositSettings(payload) {
  const settings = payload || {};
  state.admin.bankDepositSettings = settings;
  const runtimeEnabled = Boolean(settings.runtime_enabled);
  const effectiveEnabled = Boolean(settings.enabled);
  const total = Number(settings.total_destinations_count || 0);
  const active = Number(settings.active_destinations_count || 0);

  const statusEl = getEl("superBankDepositStatusText");
  if (statusEl) {
    statusEl.textContent = `${effectiveEnabled ? "Enabled for users" : "Disabled for users"} — Active cards: ${active} of ${total}`;
    statusEl.dataset.state = effectiveEnabled ? "on" : "off";
  }

  const button = getEl("superBankDepositToggleBtn");
  if (!button) return;
  const canEnable = active > 0;
  const nextEnabled = !runtimeEnabled;
  button.disabled = nextEnabled && !canEnable;
  button.dataset.nextEnabled = nextEnabled ? "true" : "false";
  button.setAttribute("aria-checked", runtimeEnabled ? "true" : "false");
  button.textContent = runtimeEnabled ? "Disable card transfers" : "Enable card transfers";
  button.classList.toggle("danger", runtimeEnabled);
  button.classList.toggle("primary", !runtimeEnabled && canEnable);
}

async function refreshSuperBankDepositSettings() {
  if (!state.admin.enabled || !state.admin.canManageSuperSettings) return;
  try {
    const out = await apiFetch("/mini-api/admin/super/bank-deposit-settings");
    renderSuperBankDepositSettings(out);
    setHint("superBankDepositHint", "");
  } catch (e) {
    const statusEl = getEl("superBankDepositStatusText");
    if (statusEl) {
      statusEl.textContent = "Could not retrieve status; use the button or superadmin bot.";
      statusEl.dataset.state = "off";
    }
    const button = getEl("superBankDepositToggleBtn");
    if (button) {
      button.disabled = true;
      button.dataset.nextEnabled = "";
      button.setAttribute("aria-checked", "false");
      button.textContent = "Unknown status; try again";
      button.classList.add("danger");
      button.classList.remove("primary");
    }
    setLocalError("superBankDepositHint", e);
  }
}

async function toggleSuperBankDepositSettings() {
  if (!state.admin.enabled || !state.admin.canManageSuperSettings) {
    throw new Error("Only superadmins may perform this action.");
  }
  const button = getEl("superBankDepositToggleBtn");
  const enabled = String(button?.dataset?.nextEnabled || "false") === "true";
  if (!window.confirm((enabled ? "Enable " : "Disable ") + "Bank card deposits" + " for users? This directly affects the ability to submit new deposits.")) return;
  if (button) button.disabled = true;
  setHint(
    "superBankDepositHint",
    enabled ? "Enabling bank card deposits..." : "Disabling bank card deposits..."
  );
  try {
    const out = await apiFetch("/mini-api/admin/super/bank-deposit-settings", {
      method: "PUT",
      body: { enabled },
    });
    renderSuperBankDepositSettings(out);
    setHint(
      "superBankDepositHint",
      enabled
        ? "Bank card deposits enabled for users."
        : "New bank card deposits are disabled; existing requests can still be reviewed.",
      "success"
    );
    await refreshWallet();
  } finally {
    if (button && state.admin.bankDepositSettings) {
      renderSuperBankDepositSettings(state.admin.bankDepositSettings);
    } else if (button) {
      button.disabled = false;
    }
  }
}

