async function checkSuperCryptoHealth() {
  setHint("superCryptoHint", "Checking rate and network services...");
  const out = await apiFetch("/mini-api/admin/super/crypto-health");
  const failedRates = (out.rate_checks || [])
    .filter((item) => !item.ok)
    .map((item) => `${item.provider}/${item.asset}`);
  const failedChains = (out.chain_checks || [])
    .filter((item) => !item.ok)
    .map((item) => item.network);
  renderSuperCryptoOpsResult(
    "Service health results",
    [
      `Rates: ${out.rates_ok ? (failedRates.length ? `Running on fallback; issue: ${failedRates.join("، ")}` : "Healthy") : failedRates.join("، ") || "Failed"}`,
      `Networks: ${out.chains_ok ? "Healthy" : failedChains.join("، ") || "Failed"}`,
      `Final status: ${out.ok ? (out.degraded ? "Running with reduced redundancy" : "Healthy") : "Needs review"}`,
    ],
    Boolean(out.ok && !out.degraded)
  );
  setHint("superCryptoHint", "Health check complete.", out.ok && !out.degraded ? "success" : "error");
}

async function checkSuperCryptoReconciliation() {
  setHint("superCryptoHint", "Reconciling blockchain and wallet ledger...");
  const out = await apiFetch("/mini-api/admin/super/crypto-reconciliation");
  renderSuperCryptoOpsResult(
    "Last 24 hours reconciliation",
    [
      `Credited invoices: ${Number(out.credited_invoices_count || 0)} items`,
      `Total credited: ${toman(out.credited_toman_total || 0)}`,
      `Transactions without invoices: ${Number(out.unmatched_onchain_count || 0)}`,
      `Invoices without chain observations: ${Number(out.missing_onchain_count || 0)}`,
      `Wallet discrepancies: ${Number(out.ledger_mismatch_count || 0)}`,
      `Final status: ${out.ok ? "Healthy" : "Needs review"}`,
    ],
    Boolean(out.ok)
  );
  setHint("superCryptoHint", "Reconciliation complete.", out.ok ? "success" : "error");
}

