let withdrawRejectModalWithdrawId = 0;
let withdrawRejectModalItem = null;
let withdrawRejectModalBound = false;
let withdrawRejectSubmitting = false;
let financeRejectModalKind = "withdraw";
let financeRejectFromReceipt = false;
let withdrawRejectPresetNodes = null;

const DEPOSIT_REJECTION_PRESETS = [
  ["🧾 Unreadable receipt", "The receipt image or details are unreadable. Please provide a clear image."],
  ["🏦 Deposit not confirmed", "The deposit was not confirmed in the destination account statement. Please check the transaction details."],
  ["💳 Details do not match", "The tracking number or deposit details do not match the request. Please submit the correct information."],
  ["🔁 Duplicate receipt", "This receipt was already submitted for another request. Please provide a different valid receipt."],
  ["✏️ Correction needed", "The submitted information is insufficient to review this deposit. Correct the information and submit a new request."],
];

function setWithdrawRejectHint(text, kind = "") {
  const el = getEl("withdrawRejectHint");
  if (!el) return;
  el.textContent = String(text || "");
  el.classList.remove("success", "error", "pending");
  if (kind) el.classList.add(kind);
}

function updateWithdrawRejectFormState() {
  const input = getEl("withdrawRejectReasonInput");
  const submitBtn = getEl("withdrawRejectSubmitBtn");
  const countEl = getEl("withdrawRejectReasonCount");
  const reason = String(input?.value || "").trim();
  const rawLength = String(input?.value || "").length;

  if (countEl) countEl.textContent = toFaDigits(Math.min(rawLength, 500));
  if (submitBtn) submitBtn.disabled = withdrawRejectSubmitting || reason.length < 3 || reason.length > 500;

  document.querySelectorAll("#withdrawRejectPresets .withdraw-reject-preset").forEach((btn) => {
    const preset = String(btn.getAttribute("data-reason") || "").trim();
    btn.classList.toggle("is-selected", Boolean(preset) && preset === reason);
  });
}

function closeWithdrawRejectModal() {
  if (withdrawRejectSubmitting) return;
  const modal = getEl("withdrawRejectModal");
  if (modal) {
    modal.classList.remove("open");
    modal.setAttribute("aria-hidden", "true");
  }
  withdrawRejectModalWithdrawId = 0;
  withdrawRejectModalItem = null;
  financeRejectModalKind = "withdraw";
  financeRejectFromReceipt = false;
  const receipt = getEl("depositReceiptModal");
  if (receipt?.classList.contains("open")) receipt.setAttribute("aria-hidden", "false");
  const input = getEl("withdrawRejectReasonInput");
  if (input) input.value = "";
  setWithdrawRejectHint("");
  updateWithdrawRejectFormState();
}

function bindWithdrawRejectModalOnce() {
  if (withdrawRejectModalBound) return;
  const modal = getEl("withdrawRejectModal");
  const closeBtn = getEl("withdrawRejectCloseBtn");
  const cancelBtn = getEl("withdrawRejectCancelBtn");
  const submitBtn = getEl("withdrawRejectSubmitBtn");
  const input = getEl("withdrawRejectReasonInput");
  const presetRoot = getEl("withdrawRejectPresets");
  if (!modal || !input || !submitBtn || !presetRoot) return;
  withdrawRejectModalBound = true;
  withdrawRejectPresetNodes = [...presetRoot.children].map((node) => node.cloneNode(true));

  if (closeBtn) closeBtn.addEventListener("click", closeWithdrawRejectModal);
  if (cancelBtn) cancelBtn.addEventListener("click", closeWithdrawRejectModal);

  if (modal) {
    modal.addEventListener("click", (ev) => {
      if (ev.target === modal) closeWithdrawRejectModal();
    });
  }

  presetRoot.addEventListener("click", (event) => {
    const btn = event.target?.closest?.(".withdraw-reject-preset");
    if (!btn || !presetRoot.contains(btn)) return;
    const reason = String(btn.dataset.reason || "").trim();
    input.value = reason;
    input.focus();
    input.setSelectionRange(input.value.length, input.value.length);
    setWithdrawRejectHint("Template reason selected; edit it if needed.", "pending");
    updateWithdrawRejectFormState();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && modal.classList.contains("open")) closeWithdrawRejectModal();
  });

  if (input) {
    input.addEventListener("input", () => {
      setWithdrawRejectHint("");
      updateWithdrawRejectFormState();
    });
  }

  if (submitBtn) {
    submitBtn.addEventListener("click", () => {
      submitWithdrawRejectModal().catch((e) => {
        setWithdrawRejectHint(e?.message || "Could not record the rejection reason.", "error");
      });
    });
  }
}

function openWithdrawRejectModal(withdrawId, item = null) {
  return openFinanceRejectModal("withdraw", withdrawId, item);
}

function openDepositRejectModal(depositId, item = null, options = {}) {
  return openFinanceRejectModal("deposit", depositId, item, options);
}

function openFinanceRejectModal(kind, requestId, item = null, options = {}) {
  const id = Number(requestId || 0);
  if (!Number.isSafeInteger(id) || id <= 0) throw new Error("Invalid request ID.");
  if (withdrawRejectSubmitting) return;

  bindWithdrawRejectModalOnce();
  const modal = getEl("withdrawRejectModal");
  const input = getEl("withdrawRejectReasonInput");
  const submitBtn = getEl("withdrawRejectSubmitBtn");
  const presetsRoot = getEl("withdrawRejectPresets");
  if (!modal || !input || !submitBtn || !presetsRoot || !withdrawRejectModalBound) {
    throw new Error("The rejection dialog is unavailable. Refresh the Mini App.");
  }

  const isDeposit = kind === "deposit";
  financeRejectModalKind = isDeposit ? "deposit" : "withdraw";
  financeRejectFromReceipt = Boolean(isDeposit && options.fromReceipt);
  withdrawRejectModalWithdrawId = id;
  withdrawRejectModalItem = item || null;
  withdrawRejectSubmitting = false;

  const title = getEl("withdrawRejectModalTitle");
  const summary = getEl("withdrawRejectSummary");
  const meta = getEl("withdrawRejectModalMeta");
  const reasonLabel = getEl("withdrawRejectReasonLabel");
  const warning = getEl("withdrawRejectWarningText");
  const presetTitle = getEl("withdrawRejectPresetsTitle");
  const kindLabel = isDeposit ? "Deposit" : "Withdrawal";
  if (title) title.textContent = "Reject " + kindLabel + " #" + toFaDigits(id);
  if (meta) meta.textContent = "The selected reason will be sent to the user and saved in the request history.";
  if (reasonLabel) reasonLabel.textContent = "Final rejection reason " + kindLabel;
  if (presetTitle) presetTitle.textContent = "Rejection templates " + kindLabel;
  if (warning) warning.textContent = "After confirmation, " + kindLabel + " will be rejected and the reason sent to the user.";
  if (submitBtn) submitBtn.textContent = "Confirm rejection " + kindLabel;
  input.value = "";
  input.placeholder = "Rejection reason " + kindLabel + " ...";

  presetsRoot.replaceChildren();
  if (isDeposit) {
    DEPOSIT_REJECTION_PRESETS.forEach(([label, reason]) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "withdraw-reject-preset";
      btn.dataset.reason = reason;
      btn.textContent = label;
      presetsRoot.appendChild(btn);
    });
  } else {
    (withdrawRejectPresetNodes || []).forEach((node) => presetsRoot.appendChild(node.cloneNode(true)));
  }

  if (summary) {
    const user = item?.tg_username
      ? "@" + String(item.tg_username).replace(/^@+/, "")
      : String(item?.tg_user_id || item?.user_id || "-");
    const name = String(item?.full_name || item?.destination_title || "-");
    summary.innerHTML =
      "<div><span>Amount</span><b>" + safeText(toman(item?.amount || 0)) + "</b></div>" +
      "<div><span>User</span><b>" + safeText(user) + "</b></div>" +
      "<div class=\"wide\"><span>" + (isDeposit ? "Destination" : "Name") +
      "</span><b>" + safeText(name) + "</b></div>";
  }

  setWithdrawRejectHint("Select a template or enter the reason manually.", "pending");
  updateWithdrawRejectFormState();

  const receipt = getEl("depositReceiptModal");
  if (financeRejectFromReceipt && receipt?.classList.contains("open")) {
    receipt.setAttribute("aria-hidden", "true");
  }
  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");
  requestAnimationFrame(() => { try { input.focus(); } catch (_) {} });
}

async function adminRejectWithdraw(withdrawId, reason) {
  const cleanReason = String(reason || "").trim();
  if (cleanReason.length < 3) throw new Error("Withdrawal rejection reason must contain at least 3 characters.");
  if (cleanReason.length > 500) throw new Error("Withdrawal rejection reason cannot exceed 500 characters.");

  return apiFetch(`/mini-api/admin/withdraws/${Number(withdrawId)}/reject`, {
    method: "POST",
    body: { reason: cleanReason },
  });
}

async function submitWithdrawRejectModal() {
  const id = Number(withdrawRejectModalWithdrawId || 0);
  const kind = financeRejectModalKind;
  const fromReceipt = financeRejectFromReceipt;
  const isDeposit = kind === "deposit";
  const input = getEl("withdrawRejectReasonInput");
  const submitBtn = getEl("withdrawRejectSubmitBtn");
  const reason = String(input?.value || "").trim();
  const kindLabel = isDeposit ? "Deposit" : "Withdrawal";

  if (!id) throw new Error("Invalid request ID.");
  if (reason.length < 3 || reason.length > 500) {
    throw new Error("Rejection reason must contain 3 to 500 characters.");
  }
  if (withdrawRejectSubmitting) return;
  withdrawRejectSubmitting = true;
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = "Submitting...";
  }
  setWithdrawRejectHint("Recording reason and rejecting " + kindLabel + "...", "pending");

  try {
    const out = isDeposit ? await adminRejectDeposit(id, reason) : await adminRejectWithdraw(id, reason);
    const notifySent = Boolean(out?.user_notify?.sent);
    withdrawRejectSubmitting = false;
    closeWithdrawRejectModal();
    if (isDeposit && fromReceipt) closeDepositReceiptModal();

    const message = kindLabel + " #" + id + " rejected" +
      (notifySent ? " and the reason was sent to the user." : "; the Telegram message failed, but the reason is saved in the history.");
    setAdminLocalHint("adminActionHint", message, notifySent ? "success" : "error");
    if (isDeposit) {
      await Promise.allSettled([refreshAdminDeposits(), refreshWallet()]);
    } else {
      await refreshAdminWithdraws();
    }
  } catch (error) {
    withdrawRejectSubmitting = false;
    if (submitBtn) submitBtn.textContent = "Confirm rejection " + kindLabel;
    updateWithdrawRejectFormState();
    throw error;
  }
}

let withdrawProofModalWithdrawId = 0;
let withdrawProofSelectedFile = null;
let withdrawProofModalBound = false;

function withdrawProofAllowedImage(file) {
  if (!file) return true;
  const type = String(file.type || "").toLowerCase();
  const name = String(file.name || "").toLowerCase();
  const okType = type.startsWith("image/");
  const okExt = [".jpg", ".jpeg", ".png", ".webp"].some((ext) => name.endsWith(ext));
  if (!okType && !okExt) {
    throw new Error("Unsupported proof image format. Only JPG, PNG or WEBP is accepted.");
  }
  const maxBytes = 3 * 1024 * 1024;
  if (Number(file.size || 0) > maxBytes) {
    throw new Error("Proof image must be no larger than 3 MB.");
  }
  return true;
}

function closeWithdrawProofModal() {
  const modal = getEl("withdrawProofModal");
  if (modal) {
    modal.classList.remove("open");
    modal.setAttribute("aria-hidden", "true");
  }
  withdrawProofModalWithdrawId = 0;
  withdrawProofSelectedFile = null;
}

function setWithdrawProofHint(text, kind = "") {
  const el = getEl("withdrawProofHint");
  if (!el) return;
  el.textContent = String(text || "");
  el.classList.remove("success", "error", "pending");
  if (kind) el.classList.add(kind);
}

async function renderWithdrawProofPreview(file) {
  const preview = getEl("withdrawProofPreview");
  const nameEl = getEl("withdrawProofFileName");
  if (!preview) return;

  if (!file) {
    preview.classList.add("hidden");
    preview.innerHTML = "";
    if (nameEl) nameEl.textContent = "No file selected";
    return;
  }

  withdrawProofAllowedImage(file);
  if (nameEl) nameEl.textContent = `${file.name || "Payment proof image"} - ${Math.ceil(Number(file.size || 0) / 1024)}KB`;

  const dataUrl = await readFileAsDataUrl(file);
  preview.innerHTML = `
    <div class="withdraw-proof-preview-card">
      <span>Selected proof preview</span>
      <img src="${dataUrl}" alt="Payment proof preview" />
    </div>
  `;
  preview.classList.remove("hidden");
  try {
    const modalCard = document.querySelector("#withdrawProofModal .withdraw-proof-modal-card");
    if (modalCard) {
      modalCard.scrollLeft = 0;
    }
    document.body.scrollLeft = 0;
    document.documentElement.scrollLeft = 0;
  } catch (_) {}
}

function bindWithdrawProofModalOnce() {
  if (withdrawProofModalBound) return;
  withdrawProofModalBound = true;

  const closeBtn = getEl("withdrawProofCloseBtn");
  const cancelBtn = getEl("withdrawProofCancelBtn");
  const submitBtn = getEl("withdrawProofSubmitBtn");
  const fileInput = getEl("withdrawProofFileInput");
  const modal = getEl("withdrawProofModal");

  if (closeBtn) closeBtn.addEventListener("click", closeWithdrawProofModal);
  if (cancelBtn) cancelBtn.addEventListener("click", closeWithdrawProofModal);

  if (modal) {
    modal.addEventListener("click", (ev) => {
      if (ev.target === modal) closeWithdrawProofModal();
    });
  }

  if (fileInput) {
    fileInput.addEventListener("change", async () => {
      const file = fileInput.files && fileInput.files[0] ? fileInput.files[0] : null;
      try {
        withdrawProofSelectedFile = file;
        await renderWithdrawProofPreview(file);
        setWithdrawProofHint(file ? "Proof image is ready to send." : "", file ? "success" : "");
      } catch (e) {
        withdrawProofSelectedFile = null;
        fileInput.value = "";
        await renderWithdrawProofPreview(null);
        setWithdrawProofHint(e.message || "Invalid proof file.", "error");
      }
    });
  }

  if (submitBtn) {
    submitBtn.addEventListener("click", () => submitWithdrawProofModal().catch((e) => {
      setWithdrawProofHint(e.message || "Could not record payment proof.", "error");
    }));
  }
}

function openWithdrawProofModal(withdrawId) {
  const id = Number(withdrawId || 0);
  if (!id) throw new Error("Invalid withdrawal ID.");

  bindWithdrawProofModalOnce();
  withdrawProofModalWithdrawId = id;
  withdrawProofSelectedFile = null;

  const modal = getEl("withdrawProofModal");
  const textInput = getEl("withdrawProofTextInput");
  const fileInput = getEl("withdrawProofFileInput");
  const submitBtn = getEl("withdrawProofSubmitBtn");
  const meta = getEl("withdrawProofModalMeta");

  if (textInput) textInput.value = "";
  if (fileInput) fileInput.value = "";
  if (submitBtn) {
    submitBtn.disabled = false;
    submitBtn.textContent = "Finalize payment";
  }
  if (meta) {
    meta.textContent = `Withdrawal #${id} Approved and debited from the wallet. Record payment proof as text or an image.`;
  }
  renderWithdrawProofPreview(null);
  setWithdrawProofHint("Provide at least one: proof text or a proof image.", "pending");

  if (!modal) throw new Error("Payment proof dialog not found.");
  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");
  setTimeout(() => {
    try { textInput?.focus(); } catch (_) {}
  }, 50);
}

async function adminSaveWithdrawProof(withdrawId, proofText, file) {
  const body = { proof_text: String(proofText || "").trim() };
  if (file) {
    withdrawProofAllowedImage(file);
    body.filename = String(file.name || "withdraw-proof.jpg");
    body.content_type = String(file.type || "image/jpeg");
    body.data_base64 = await readFileAsDataUrl(file);
  }
  return apiFetch(`/mini-api/admin/withdraws/${Number(withdrawId)}/proof`, {
    method: "POST",
    body,
  });
}

async function submitWithdrawProofModal() {
  const id = Number(withdrawProofModalWithdrawId || 0);
  if (!id) throw new Error("Invalid withdrawal ID.");

  const textInput = getEl("withdrawProofTextInput");
  const submitBtn = getEl("withdrawProofSubmitBtn");
  const proofText = String(textInput?.value || "").trim();
  const file = withdrawProofSelectedFile || null;

  if (!proofText && !file) {
    throw new Error("Proof text, a tracking code or a proof image is required to record payment.");
  }

  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = "Submitting...";
  }
  setWithdrawProofHint("Recording payment proof and finalizing withdrawal...", "pending");

  try {
    await adminSaveWithdrawProof(id, proofText, file);
    const tracking = proofText || `image_receipt_${Date.now()}`;
    await apiFetch(`/mini-api/admin/withdraws/${id}/paid`, {
      method: "POST",
      body: { paid_tracking: tracking.slice(0, 128) },
    });

    setWithdrawProofHint("Payment proof recorded and withdrawal marked as paid.", "success");
    closeWithdrawProofModal();
    await refreshAdminWithdraws();
  } finally {
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = "Finalize payment";
    }
  }
}

