function wireAdminAccordion() {
  const items = Array.from(document.querySelectorAll("#view-admin .accordion-item"));
  if (!items.length) return;
  items.forEach((item) => {
    item.addEventListener("toggle", () => {
      if (!item.open) return;
      items.forEach((other) => {
        if (other !== item) other.open = false;
      });
    });
  });
}

