  const receiptModal = getEl("receiptModal");
  if (receiptModal) {
    receiptModal.addEventListener("click", (e) => {
      if (e.target === receiptModal) closeReceiptModal();
    });
  }

  let authOk = false;
  try {
    setSplashStatus("Connecting securely to your account...");
    if (restoreMiniSession()) {
      authOk = true;
      setBadge("success", "Connected");
    } else {
      await exchangeSession();
      authOk = true;
    }
  } catch (err) {
    clearMiniSession();
    state.authReady = false;
    setBadge("error", String(err.message || "Authentication error"));
  }

  if (!authOk) return;
  tracking.openLinked();

  startMiniSocket();
  setSplashStatus("Loading games and wallet...");
